import React, { Component } from 'react';
import { default as AsyncSelect } from 'react-select/async';
import {
    requestHeaderGETWithAuth,
    requestHeaderPOSTWithAuth,
    requestHeaderPUTWithAuth,
    requestHeaderDELETEWithAuth,
} from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const FILE_NAME = "InstagramReelViewer.js";

const REEL_PAGE_SIZE = 20;

// Tag APIs (TagController) are tenant-scoped via a path variable. The admin panel
// has no per-user tenant concept, so reel tagging uses a single default tenant.
const DEFAULT_TENANT_ID = 1;

// Persists whether the tags panel is shown; defaults to hidden when unset.
const TAGS_VISIBLE_STORAGE_KEY = 'instagramReelViewer.showTags';

// Persists whether the comments panel is shown; defaults to hidden when unset.
const COMMENTS_VISIBLE_STORAGE_KEY = 'instagramReelViewer.showComments';

// Persists auto-advance (play next reel when current ends); defaults to off when unset.
const AUTO_ADVANCE_STORAGE_KEY = 'instagramReelViewer.autoAdvance';

// Grid mode: view X reels simultaneously, where X is chosen between GRID_MIN and GRID_MAX.
const GRID_MIN = 2;
const GRID_MAX = 10;
const DEFAULT_GRID_COUNT = 4;
// Persists the chosen grid count across sessions.
const GRID_COUNT_STORAGE_KEY = 'instagramReelViewer.gridCount';

// Reads the saved grid count, clamped to [GRID_MIN, GRID_MAX]; falls back to default.
const clampGridCount = (n) => Math.max(GRID_MIN, Math.min(GRID_MAX, n));
const readStoredGridCount = () => {
    const stored = parseInt(localStorage.getItem(GRID_COUNT_STORAGE_KEY), 10);
    return isNaN(stored) ? DEFAULT_GRID_COUNT : clampGridCount(stored);
};

// Color per like amount; used for the quick-like buttons and the floating heart popup.
const LIKE_COLORS = {
    1: '#ff3040',   // red - single like
    2: '#ff4fa3',   // pink
    5: '#8a2be2',   // purple
    10: '#ff8c00',  // orange
};
const DEFAULT_LIKE_COLOR = '#ff3040';

const likeColorFor = (amount) => LIKE_COLORS[amount] || DEFAULT_LIKE_COLOR;

class InstagramReelViewer extends Component {

    constructor(props) {
        super(props);
        const params = new URLSearchParams(this.props.location.search);
        const startPage = parseInt(params.get('startPage')) || 1;
        const startReelId = parseInt(params.get('startReelId')) || null;
        // Random mode when there's no profileId in the route (e.g. /instagram/reels/random),
        // OR when a profile route explicitly opts in via ?random=true (shuffle this profile's reels).
        const isRandom = !this.props.match.params.internalProfileId
            || params.get('random') === 'true';

        // Optional deep-link into a tag-filtered viewer: ?tags=a,b&tagMode=AND
        const tagsParam = params.get('tags');
        const initialTags = tagsParam
            ? tagsParam.split(',').map(t => t.trim()).filter(t => t.length > 0)
            : [];
        const tagModeParam = (params.get('tagMode') || '').toUpperCase();
        const initialTagMode = tagModeParam === 'AND' ? 'AND' : 'OR';

        this.state = {
            isLoaded: false,
            isRandom: isRandom,
            reels: [],
            currentIndex: 0,
            page: startPage,
            totalPages: 0,
            totalElements: 0,
            reelBlobUrls: {}, // { reelId: blobUrl }
            loadingReelIds: {}, // { reelId: true }
            isPaused: false,
            showOverlay: false,
            currentTime: 0,
            duration: 0,
            isSeeking: false,
            startReelId: startReelId,
            likeCounts: {}, // { reelId: count }
            viewCounts: {}, // { reelId: count }
            likingReelIds: {}, // { reelId: true } - tracks in-flight like requests
            likeAnimatingIds: {}, // { reelId: true } - tracks pop animation
            likeColorIds: {}, // { reelId: color } - color of the most recent like (by amount)
            isCleanView: false, // hides all UI overlays except video
            // Auto-advance to the next reel when the current one finishes.
            // Defaults to off; remembered in localStorage.
            autoAdvance: localStorage.getItem(AUTO_ADVANCE_STORAGE_KEY) === 'true',
            tagsByReelId: {}, // { reelId: [tagName, ...] }
            tagInputByReelId: {}, // { reelId: currentInputText }
            tagBusyReelIds: {}, // { reelId: true } - in-flight add/delete/fetch
            // Tags panel visibility is a single global preference persisted in
            // localStorage (hidden by default). Applies to all reels.
            showTags: localStorage.getItem(TAGS_VISIBLE_STORAGE_KEY) === 'true',
            tagSuggestionsByReelId: {}, // { reelId: [{name, usageCount}, ...] }
            // ---- Comments (COMMENT engagements) ----
            commentsByReelId: {}, // { reelId: [{id, comment, createdOn}, ...] } newest first
            commentInputByReelId: {}, // { reelId: currentInputText }
            commentBusyReelIds: {}, // { reelId: true } - in-flight add/delete/fetch
            // Comments panel visibility is a single global preference persisted in
            // localStorage (hidden by default). Applies to all reels.
            showComments: localStorage.getItem(COMMENTS_VISIBLE_STORAGE_KEY) === 'true',
            // ---- Grid mode: view X reels simultaneously ----
            gridActive: false,          // grid overlay visible
            gridCount: readStoredGridCount(), // how many reels to show at once (GRID_MIN..GRID_MAX)
            gridStart: 0,               // index of the first reel shown in the grid (paging offset)
            gridReels: [],              // the reels currently tiled in the grid
            // ---- View-by-tags filter ----
            // selectedTags: tag-name strings used to restrict the loaded reels;
            // tagMatchMode: 'OR' = reels with any tag, 'AND' = reels with all tags.
            selectedTags: initialTags,
            tagMatchMode: initialTagMode,
            // When the viewer is opened for a specific profile, the tag-filter options are
            // scoped to that profile's own tags (names), fetched once from the profile API.
            // null = not profile-scoped (global tag search is used instead).
            profileTagNames: null,
        };
        this.tagSuggestTimeout = null;
        this.containerRef = React.createRef();
        this.videoRefs = {};
        this.overlayTimeout = null;
        this.timelineRef = React.createRef();
        this.lastPinchDistance = null;
    }

    componentDidMount() {
        document.title = "Instagram Reel Viewer";
        this.injectAnimationStyles();
        this.fetchReels();
        // When opened for a specific profile, scope the tag-filter options to that
        // profile's own tags. Without a profile (random/global mode) the filter falls
        // back to a global tag search.
        if (this.props.match.params.internalProfileId) {
            this.fetchProfileTagNames(this.props.match.params.internalProfileId);
        }
        document.addEventListener('keydown', this.handleKeyDown);
        document.addEventListener('fullscreenchange', this.handleFullscreenChange);
        document.addEventListener('webkitfullscreenchange', this.handleFullscreenChange);
        this.startTimeUpdate();
    }

    componentWillUnmount() {
        document.removeEventListener('keydown', this.handleKeyDown);
        document.removeEventListener('fullscreenchange', this.handleFullscreenChange);
        document.removeEventListener('webkitfullscreenchange', this.handleFullscreenChange);
        // Revoke all blob URLs
        Object.values(this.state.reelBlobUrls).forEach(url => URL.revokeObjectURL(url));
        if (this.overlayTimeout) clearTimeout(this.overlayTimeout);
        if (this.timeUpdateInterval) cancelAnimationFrame(this.timeUpdateInterval);
        if (this.clickTimeout) clearTimeout(this.clickTimeout);
        if (this.tagSuggestTimeout) clearTimeout(this.tagSuggestTimeout);
        // Remove injected style
        if (this.styleEl) {
            document.head.removeChild(this.styleEl);
        }
    }

    injectAnimationStyles() {
        const css = `
            @keyframes heartPop {
                0% { transform: translate(-50%, -50%) scale(0); opacity: 1; }
                30% { transform: translate(-50%, -50%) scale(1.3); opacity: 1; }
                60% { transform: translate(-50%, -50%) scale(1); opacity: 0.9; }
                100% { transform: translate(-50%, -50%) scale(1.1); opacity: 0; }
            }
            @keyframes heartFade {
                0% { opacity: 0; transform: scale(0.3); }
                20% { opacity: 1; transform: scale(1.2); }
                50% { opacity: 1; transform: scale(1); }
                100% { opacity: 0; transform: scale(1) translateY(-30px); }
            }
            @keyframes spin {
                0% { transform: rotate(0deg); }
                100% { transform: rotate(360deg); }
            }
        `;
        this.styleEl = document.createElement('style');
        this.styleEl.textContent = css;
        document.head.appendChild(this.styleEl);
    }

    startTimeUpdate() {
        const update = () => {
            const { reels, currentIndex, isSeeking } = this.state;
            const reel = reels[currentIndex];
            if (reel && !isSeeking) {
                const videoEl = this.videoRefs[reel.id];
                if (videoEl) {
                    this.setState({
                        currentTime: videoEl.currentTime || 0,
                        duration: videoEl.duration || 0,
                    });
                }
            }
            this.timeUpdateInterval = requestAnimationFrame(update);
        };
        this.timeUpdateInterval = requestAnimationFrame(update);
    }

    fetchReels() {
        const { page, isRandom, selectedTags, tagMatchMode } = this.state;
        const profileId = this.props.match.params.internalProfileId;
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/reels';
        const userData = getUserDataFromLocalStorage();

        // Only send tagFilter when at least one tag is selected; mode is AND/OR.
        // Omitting it (null) keeps the existing unfiltered behavior.
        const tagFilter = selectedTags.length > 0 ? { tags: selectedTags, mode: tagMatchMode } : null;

        // In random mode, scope to the profile when the route has one (per-profile shuffle),
        // otherwise shuffle across all profiles (global random).
        const reqData = isRandom
            ? { page, size: REEL_PAGE_SIZE, search: null, profileId: profileId ? Number(profileId) : null, downloadedOnly: true, random: true, tagFilter }
            : { page, size: REEL_PAGE_SIZE, search: null, profileId: Number(profileId), downloadedOnly: true, tagFilter };
        Logger(FILE_NAME, "fetchReels", "", "reqData", reqData);

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                logoutProcedureForLocalStorage();
                reloadPage();
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(
            (result) => {
                Logger(FILE_NAME, "fetchReels", "FETCH_1", "result", result);
                const pageData = result.data;
                const downloadedReels = pageData.content || [];
                this.setState(prevState => {
                    // In random mode pages are reshuffled server-side and may repeat reels,
                    // so drop any that are already loaded to avoid duplicate keys / immediate repeats.
                    let incomingReels = downloadedReels;
                    if (prevState.isRandom) {
                        const existingIds = new Set(prevState.reels.map(r => r.id));
                        incomingReels = downloadedReels.filter(r => !existingIds.has(r.id));
                    }
                    const allReels = [...prevState.reels, ...incomingReels];
                    let currentIndex = prevState.currentIndex;

                    // If startReelId is set and we haven't positioned yet, find it
                    if (prevState.startReelId) {
                        const foundIndex = allReels.findIndex(r => r.id === prevState.startReelId);
                        if (foundIndex !== -1) {
                            currentIndex = foundIndex;
                        }
                    }

                    return {
                        isLoaded: true,
                        reels: allReels,
                        currentIndex: currentIndex,
                        totalPages: pageData.totalPages || 0,
                        totalElements: pageData.totalElements || 0,
                        startReelId: null, // clear after first use
                    };
                }, () => {
                    const { reels, currentIndex } = this.state;
                    // Preload current and next reel
                    if (reels.length > 0) {
                        this.preloadReel(reels[currentIndex].id);
                        this.fetchLikeCount(reels[currentIndex].id);
                        this.fetchViewCount(reels[currentIndex].id);
                        this.fetchTags(reels[currentIndex].id);
                        this.fetchComments(reels[currentIndex].id);
                        this.recordView(reels[currentIndex].id);
                        if (currentIndex + 1 < reels.length) {
                            this.preloadReel(reels[currentIndex + 1].id);
                        }
                    }
                });
            },
            (error) => {
                Logger(FILE_NAME, "fetchReels", "FETCH_1", "error", error);
                this.setState({ isLoaded: true });
            }
        );
    }

    preloadReel(reelId) {
        const { reelBlobUrls, loadingReelIds } = this.state;
        if (reelBlobUrls[reelId] || loadingReelIds[reelId]) return;

        this.setState(prev => ({ loadingReelIds: { ...prev.loadingReelIds, [reelId]: true } }));

        const userData = getUserDataFromLocalStorage();
        const fileUrl = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/reel/' + reelId + '/file';

        fetch(fileUrl, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.blob();
            throw new Error("HTTP status is " + response.status);
        })
        .then(blob => {
            const objectUrl = URL.createObjectURL(blob);
            this.setState(prev => ({
                reelBlobUrls: { ...prev.reelBlobUrls, [reelId]: objectUrl },
                loadingReelIds: { ...prev.loadingReelIds, [reelId]: false },
            }));
        })
        .catch(error => {
            Logger(FILE_NAME, "preloadReel", "", "error", error);
            this.setState(prev => ({ loadingReelIds: { ...prev.loadingReelIds, [reelId]: false } }));
        });
    }

    fetchLikeCount(reelId) {
        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/engage/count?type=REEL&internalContentId=' + reelId + '&action=LIKE';

        fetch(url, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            this.setState(prev => ({
                likeCounts: { ...prev.likeCounts, [reelId]: result.data }
            }));
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchLikeCount", "", "error", error);
        });
    }

    fetchViewCount(reelId) {
        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/engage/count?type=REEL&internalContentId=' + reelId + '&action=VIEW';

        fetch(url, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            this.setState(prev => ({
                viewCounts: { ...prev.viewCounts, [reelId]: result.data }
            }));
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchViewCount", "", "error", error);
        });
    }

    recordView(reelId) {
        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/engage';
        // value = 1 so counts aggregate correctly (backend sums the 'value' column)
        const reqData = { type: 'REEL', internalContentId: reelId, action: 'VIEW', value: 1 };

        fetch(url, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(() => {
            this.fetchViewCount(reelId);
        })
        .catch(error => {
            Logger(FILE_NAME, "recordView", "", "error", error);
        });
    }

    // ---------- tags (TagController, tenant-scoped by path) ----------

    // GET /v1/{tenantId}/tags/{mediaId} — tags attached to a reel within the tenant.
    fetchTags(reelId) {
        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/' + DEFAULT_TENANT_ID + '/tags/' + reelId;

        fetch(url, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            this.setState(prev => ({
                tagsByReelId: { ...prev.tagsByReelId, [reelId]: result.data || [] }
            }));
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchTags", "", "error", error);
        });
    }

    // PUT /v1/{tenantId}/tags/{mediaId} — add one tag (backend normalizes: trims,
    // lowercases, strips leading '#'). Graceful/idempotent on the server.
    addTag = (reelId) => {
        const raw = (this.state.tagInputByReelId[reelId] || '').trim();
        if (!raw || this.state.tagBusyReelIds[reelId]) return;

        this.setState(prev => ({ tagBusyReelIds: { ...prev.tagBusyReelIds, [reelId]: true } }));

        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/' + DEFAULT_TENANT_ID + '/tags/' + reelId;
        const reqData = { tag: raw };

        fetch(url, requestHeaderPUTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(() => {
            this.setState(prev => ({
                tagInputByReelId: { ...prev.tagInputByReelId, [reelId]: '' },
                tagBusyReelIds: { ...prev.tagBusyReelIds, [reelId]: false },
                tagSuggestionsByReelId: { ...prev.tagSuggestionsByReelId, [reelId]: [] },
            }));
            this.fetchTags(reelId);
        })
        .catch(error => {
            Logger(FILE_NAME, "addTag", "", "error", error);
            this.setState(prev => ({ tagBusyReelIds: { ...prev.tagBusyReelIds, [reelId]: false } }));
        });
    }

    // DELETE /v1/{tenantId}/tags/{mediaId} — remove one tag. Graceful no-op on the server.
    deleteTag = (reelId, tagName) => {
        if (this.state.tagBusyReelIds[reelId]) return;

        this.setState(prev => ({ tagBusyReelIds: { ...prev.tagBusyReelIds, [reelId]: true } }));

        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/' + DEFAULT_TENANT_ID + '/tags/' + reelId;
        const reqData = { tag: tagName };

        fetch(url, requestHeaderDELETEWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(() => {
            this.setState(prev => ({
                // optimistic removal, then reconcile with server
                tagsByReelId: {
                    ...prev.tagsByReelId,
                    [reelId]: (prev.tagsByReelId[reelId] || []).filter(t => t !== tagName),
                },
                tagBusyReelIds: { ...prev.tagBusyReelIds, [reelId]: false },
            }));
            this.fetchTags(reelId);
        })
        .catch(error => {
            Logger(FILE_NAME, "deleteTag", "", "error", error);
            this.setState(prev => ({ tagBusyReelIds: { ...prev.tagBusyReelIds, [reelId]: false } }));
        });
    }

    handleTagInputChange = (reelId, value) => {
        this.setState(prev => ({
            tagInputByReelId: { ...prev.tagInputByReelId, [reelId]: value }
        }));
        this.scheduleTagSuggestions(reelId, value);
    }

    // Debounced typeahead: query existing tags via POST /v1/tags/search (substring match).
    scheduleTagSuggestions = (reelId, value) => {
        if (this.tagSuggestTimeout) clearTimeout(this.tagSuggestTimeout);

        const term = (value || '').trim();
        if (term.length < 1) {
            // nothing to search — clear any open suggestions
            this.setState(prev => ({
                tagSuggestionsByReelId: { ...prev.tagSuggestionsByReelId, [reelId]: [] }
            }));
            return;
        }

        this.tagSuggestTimeout = setTimeout(() => this.fetchTagSuggestions(reelId, term), 250);
    }

    fetchTagSuggestions(reelId, term) {
        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/tags/search';
        // most-used matches first; small page for a typeahead dropdown
        const reqData = { page: 1, size: 8, search: term, sortBy: 'USAGE' };

        fetch(url, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            const pageData = (result && result.data) || {};
            const alreadyOnReel = new Set(this.state.tagsByReelId[reelId] || []);
            // don't suggest tags already attached to this reel
            const suggestions = (pageData.content || []).filter(s => !alreadyOnReel.has(s.name));
            this.setState(prev => ({
                tagSuggestionsByReelId: { ...prev.tagSuggestionsByReelId, [reelId]: suggestions }
            }));
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchTagSuggestions", "", "error", error);
        });
    }

    selectTagSuggestion = (reelId, name) => {
        // set the input to the picked suggestion, then add it
        this.setState(prev => ({
            tagInputByReelId: { ...prev.tagInputByReelId, [reelId]: name },
            tagSuggestionsByReelId: { ...prev.tagSuggestionsByReelId, [reelId]: [] },
        }), () => this.addTag(reelId));
    }

    handleTagInputKeyDown = (event, reelId) => {
        // keep the viewer's global key handlers (space/j/k/l...) from firing while typing
        event.stopPropagation();
        if (event.key === 'Enter') {
            event.preventDefault();
            this.addTag(reelId);
        }
    }

    // Toggles the global tags-panel visibility and remembers it in localStorage.
    toggleTagsPanel = () => {
        this.setState(prev => {
            const next = !prev.showTags;
            localStorage.setItem(TAGS_VISIBLE_STORAGE_KEY, String(next));
            return { showTags: next };
        });
    }

    // ---------- view-by-tags filter ----------

    // Fetches this profile's own tag names (for profile-scoped tag filtering) from the
    // profile detail API, which returns data.tags as [{name, count}, ...].
    fetchProfileTagNames(profileId) {
        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/profile/' + profileId;

        fetch(url, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            const tags = (result && result.data && result.data.tags) || [];
            const names = tags.map(t => (typeof t === 'string' ? t : t.name)).filter(Boolean);
            this.setState({ profileTagNames: names });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchProfileTagNames", "", "error", error);
            // Leave profileTagNames null so the filter falls back to global tag search.
        });
    }

    // AsyncSelect loader for the tag filter.
    // Profile-scoped: when the viewer is opened for a specific profile, the options are
    // that profile's own tags (filtered client-side by the typed term).
    // Otherwise (random/global mode): a global tag search via POST /v1/tags/search.
    loadTagFilterOptions = (term) => {
        const search = (term || '').trim().toLowerCase();

        // Profile-scoped options: filter the profile's own tag names in-memory.
        if (Array.isArray(this.state.profileTagNames)) {
            const matches = this.state.profileTagNames
                .filter(name => !search || name.toLowerCase().includes(search))
                .map(name => ({ value: name, label: name }));
            return Promise.resolve(matches);
        }

        // Global fallback: debounced tag search across all tags.
        return new Promise((resolve) => {
            if (this.tagSuggestTimeout) clearTimeout(this.tagSuggestTimeout);

            this.tagSuggestTimeout = setTimeout(() => {
                const userData = getUserDataFromLocalStorage();
                const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/tags/search';
                // most-used matches first; small page for a typeahead dropdown
                const reqData = { page: 1, size: 8, search: search || null, sortBy: 'USAGE' };

                fetch(url, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
                .then(response => {
                    if (response.status === 200) return response.json();
                    throw new Error("HTTP status is " + response.status);
                })
                .then(result => {
                    const pageData = (result && result.data) || {};
                    const options = (pageData.content || []).map(s => ({ value: s.name, label: s.name }));
                    resolve(options);
                })
                .catch(error => {
                    Logger(FILE_NAME, "loadTagFilterOptions", "", "error", error);
                    resolve([]);
                });
            }, 250);
        });
    }

    // Resets the loaded reel pool and re-fetches from page 1 whenever the tag filter
    // changes, so new results replace (not append onto) the previously loaded reels.
    applyTagFilter = () => {
        // Revoke existing blob URLs to avoid leaks (mirrors componentWillUnmount).
        Object.values(this.state.reelBlobUrls).forEach(url => URL.revokeObjectURL(url));
        this.setState({
            reels: [],
            currentIndex: 0,
            page: 1,
            totalPages: 0,
            totalElements: 0,
            reelBlobUrls: {},
            loadingReelIds: {},
            startReelId: null,
            gridActive: false,
            gridReels: [],
        }, () => this.fetchReels());
    }

    // react-select onChange: update the selected tag names, then reset & re-fetch.
    handleTagFilterChange = (choices) => {
        this.setState(
            { selectedTags: (choices || []).map(o => o.value) },
            () => this.applyTagFilter()
        );
    }

    // AND/OR toggle onChange: update the match mode; only re-fetch when tags are chosen
    // (toggling the mode with no tags selected would be a pointless refetch).
    handleTagModeChange = (mode) => {
        this.setState(
            { tagMatchMode: mode },
            () => { if (this.state.selectedTags.length > 0) this.applyTagFilter(); }
        );
    }

    // ---------- comments (COMMENT engagements) ----------

    // GET /v1/instagram/engage/comments?type=REEL&internalContentId=<reelId>
    // Returns the comment rows (newest first), each carrying id/comment/createdOn.
    fetchComments(reelId) {
        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/engage/comments?type=REEL&internalContentId=' + reelId;

        fetch(url, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            this.setState(prev => ({
                commentsByReelId: { ...prev.commentsByReelId, [reelId]: result.data || [] }
            }));
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchComments", "", "error", error);
        });
    }

    // POST /v1/instagram/engage with action=COMMENT — adds one comment to the reel.
    addComment = (reelId) => {
        const raw = (this.state.commentInputByReelId[reelId] || '').trim();
        if (!raw || this.state.commentBusyReelIds[reelId]) return;

        this.setState(prev => ({ commentBusyReelIds: { ...prev.commentBusyReelIds, [reelId]: true } }));

        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/engage';
        const reqData = { type: 'REEL', internalContentId: reelId, action: 'COMMENT', comment: raw };

        fetch(url, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(() => {
            this.setState(prev => ({
                commentInputByReelId: { ...prev.commentInputByReelId, [reelId]: '' },
                commentBusyReelIds: { ...prev.commentBusyReelIds, [reelId]: false },
            }));
            this.fetchComments(reelId);
        })
        .catch(error => {
            Logger(FILE_NAME, "addComment", "", "error", error);
            this.setState(prev => ({ commentBusyReelIds: { ...prev.commentBusyReelIds, [reelId]: false } }));
        });
    }

    // DELETE /v1/instagram/engage/{id} — removes one comment by its engagement id.
    deleteComment = (reelId, commentId) => {
        if (this.state.commentBusyReelIds[reelId]) return;

        this.setState(prev => ({ commentBusyReelIds: { ...prev.commentBusyReelIds, [reelId]: true } }));

        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/engage/' + commentId;

        fetch(url, requestHeaderDELETEWithAuth(null, userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(() => {
            this.setState(prev => ({
                // optimistic removal, then reconcile with server
                commentsByReelId: {
                    ...prev.commentsByReelId,
                    [reelId]: (prev.commentsByReelId[reelId] || []).filter(c => c.id !== commentId),
                },
                commentBusyReelIds: { ...prev.commentBusyReelIds, [reelId]: false },
            }));
            this.fetchComments(reelId);
        })
        .catch(error => {
            Logger(FILE_NAME, "deleteComment", "", "error", error);
            this.setState(prev => ({ commentBusyReelIds: { ...prev.commentBusyReelIds, [reelId]: false } }));
        });
    }

    handleCommentInputChange = (reelId, value) => {
        this.setState(prev => ({
            commentInputByReelId: { ...prev.commentInputByReelId, [reelId]: value }
        }));
    }

    handleCommentInputKeyDown = (event, reelId) => {
        // keep the viewer's global key handlers (space/j/k/l...) from firing while typing
        event.stopPropagation();
        if (event.key === 'Enter') {
            event.preventDefault();
            this.addComment(reelId);
        }
    }

    // Toggles the global comments-panel visibility and remembers it in localStorage.
    toggleCommentsPanel = () => {
        this.setState(prev => {
            const next = !prev.showComments;
            localStorage.setItem(COMMENTS_VISIBLE_STORAGE_KEY, String(next));
            return { showComments: next };
        });
    }

    // Likes the current reel by the given amount (number of likes to record in one call).
    // Defaults to 1, e.g. for the double-click / 'L' shortcut.
    likeCurrentReel = (amount = 1) => {
        const { reels, currentIndex, likingReelIds } = this.state;
        const reel = reels[currentIndex];
        if (!reel || likingReelIds[reel.id]) return;

        const likeAmount = Number(amount) > 0 ? Number(amount) : 1;
        const likeColor = likeColorFor(likeAmount);

        // Trigger pop animation, colored by the like amount
        this.setState(prev => ({
            likingReelIds: { ...prev.likingReelIds, [reel.id]: true },
            likeAnimatingIds: { ...prev.likeAnimatingIds, [reel.id]: true },
            likeColorIds: { ...prev.likeColorIds, [reel.id]: likeColor },
        }));

        // Clear animation after it completes
        setTimeout(() => {
            this.setState(prev => ({
                likeAnimatingIds: { ...prev.likeAnimatingIds, [reel.id]: false },
            }));
        }, 1200);

        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/engage';
        // value = number of likes to record in this single call (backend sums the 'value' column)
        const reqData = { type: 'REEL', internalContentId: reel.id, action: 'LIKE', value: likeAmount };

        fetch(url, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(() => {
            // Optimistically increment count by the amount, then refresh from server
            this.setState(prev => ({
                likeCounts: { ...prev.likeCounts, [reel.id]: (prev.likeCounts[reel.id] || 0) + likeAmount },
                likingReelIds: { ...prev.likingReelIds, [reel.id]: false },
            }));
            this.fetchLikeCount(reel.id);
        })
        .catch(error => {
            Logger(FILE_NAME, "likeCurrentReel", "", "error", error);
            this.setState(prev => ({ likingReelIds: { ...prev.likingReelIds, [reel.id]: false } }));
        });
    }

    // Opens the Instagram profile page for the given reel in a new browser tab.
    // Prefers the reel's own profile id, then the route param, then a default.
    openProfileInNewTab = (reel) => {
        const profileId =
            (reel && (reel.internalProfileId || reel.profileId)) ||
            this.props.match.params.internalProfileId ||
            15;
        // The profile page lives in this same (HashRouter) app, so resolve against the
        // current origin rather than a hardcoded localhost host — otherwise the link
        // always points at localhost no matter where the panel is actually served.
        const url = window.location.origin + '/#/instagram/profile/' + profileId;
        window.open(url, '_blank', 'noopener,noreferrer');
    }

    // Fired when a reel finishes playing. If auto-advance is on and this is the
    // active reel, move to the next one; if it's the last reel, replay it.
    handleReelEnded = (reelId) => {
        if (!this.state.autoAdvance) return;
        const { reels, currentIndex } = this.state;
        const reel = reels[currentIndex];
        if (!reel || reel.id !== reelId) return;

        if (currentIndex < reels.length - 1) {
            this.goToNext();
        } else {
            // Last reel — no next slide, so replay it.
            const videoEl = this.videoRefs[reelId];
            if (videoEl) {
                videoEl.currentTime = 0;
                videoEl.play().catch(() => {});
            }
        }
    }

    // Toggles auto-advance and remembers the choice in localStorage.
    toggleAutoAdvance = () => {
        this.setState(prev => {
            const next = !prev.autoAdvance;
            localStorage.setItem(AUTO_ADVANCE_STORAGE_KEY, String(next));
            return { autoAdvance: next };
        });
    }

    // ---------- grid mode: view X reels simultaneously ----------

    // Returns `count` reels to tile, starting at index `start` and taking the
    // following ones in order. If the loaded pool is smaller than count, it wraps
    // around so the grid always shows exactly `count` tiles.
    buildGridReels(count, start) {
        const { reels } = this.state;
        if (reels.length === 0) return [];
        const tiles = [];
        for (let i = 0; i < count; i++) {
            tiles.push(reels[(start + i) % reels.length]);
        }
        return tiles;
    }

    // Opens the grid overlay showing gridCount reels starting at the current reel.
    openGrid = () => {
        // pause the underlying single-view video while the grid is up
        const { reels, currentIndex, gridCount } = this.state;
        const reel = reels[currentIndex];
        if (reel && this.videoRefs[reel.id]) this.videoRefs[reel.id].pause();

        const gridReels = this.buildGridReels(gridCount, currentIndex);
        gridReels.forEach(r => this.preloadReel(r.id));
        this.setState({ gridActive: true, gridStart: currentIndex, gridReels });
    }

    // Changes how many reels are shown at once (clamped, persisted) and rebuilds the grid.
    setGridCount = (count) => {
        const next = clampGridCount(count);
        localStorage.setItem(GRID_COUNT_STORAGE_KEY, String(next));
        const gridReels = this.buildGridReels(next, this.state.gridStart);
        gridReels.forEach(r => this.preloadReel(r.id));
        this.setState({ gridCount: next, gridReels });
    }

    // Pages the grid forward (+1) or backward (-1) by one full screen of gridCount reels.
    scrollGrid = (direction) => {
        const { reels, gridCount, gridStart, page, totalPages, isRandom } = this.state;
        if (reels.length === 0) return;

        let nextStart = gridStart + direction * gridCount;
        // clamp so we don't scroll before the first reel
        if (nextStart < 0) nextStart = 0;
        // don't page past the end of what's loaded (keep a full grid where possible)
        const maxStart = Math.max(0, reels.length - gridCount);
        if (nextStart > maxStart) nextStart = maxStart;

        const gridReels = this.buildGridReels(gridCount, nextStart);
        gridReels.forEach(r => this.preloadReel(r.id));
        this.setState({ gridStart: nextStart, gridReels });

        // Load more reels when nearing the end of the loaded list.
        if (direction > 0 && nextStart + gridCount >= reels.length - gridCount) {
            if (isRandom) {
                const nextPage = page < totalPages ? page + 1 : 1;
                this.setState({ page: nextPage }, () => this.fetchReels());
            } else if (page < totalPages) {
                this.setState({ page: page + 1 }, () => this.fetchReels());
            }
        }
    }

    // Closes the grid and resumes the underlying single reel.
    closeGrid = () => {
        this.setState({ gridActive: false, gridReels: [] }, () => this.playCurrentReel());
    }

    // Jump from a grid tile into the normal full-screen single view for that reel.
    openReelFromGrid = (reelId) => {
        const index = this.state.reels.findIndex(r => r.id === reelId);
        if (index === -1) return;
        this.setState({ gridActive: false, gridReels: [], currentIndex: index, isPaused: false }, () => {
            this.playCurrentReel();
            this.fetchLikeCount(reelId);
            this.fetchViewCount(reelId);
            this.fetchTags(reelId);
            this.fetchComments(reelId);
            this.recordView(reelId);
        });
    }

    handleVideoClick = (event, reelId) => {
        if (this.clickTimeout) {
            // Double click detected — like
            clearTimeout(this.clickTimeout);
            this.clickTimeout = null;
            this.likeCurrentReel();
        } else {
            // Wait to see if it's a double click
            this.clickTimeout = setTimeout(() => {
                this.clickTimeout = null;
                this.togglePause();
            }, 250);
        }
    }

    handleKeyDown = (event) => {
        // In grid mode, arrows/j/k page the grid and Escape closes it.
        if (this.state.gridActive) {
            if (event.key === 'ArrowDown' || event.key === 'j' || event.key === 'ArrowRight') {
                event.preventDefault();
                this.scrollGrid(1);
            } else if (event.key === 'ArrowUp' || event.key === 'k' || event.key === 'ArrowLeft') {
                event.preventDefault();
                this.scrollGrid(-1);
            } else if (event.key === 'Escape') {
                event.preventDefault();
                this.closeGrid();
            }
            return;
        }
        if (event.key === 'ArrowDown' || event.key === 'j') {
            event.preventDefault();
            this.goToNext();
        } else if (event.key === 'ArrowUp' || event.key === 'k') {
            event.preventDefault();
            this.goToPrev();
        } else if (event.key === ' ') {
            event.preventDefault();
            this.togglePause();
        } else if (event.key === 'l') {
            event.preventDefault();
            this.likeCurrentReel();
        } else if (event.key === 'f') {
            event.preventDefault();
            this.toggleFullscreen();
        } else if (event.key === 'Escape') {
            this.props.history.goBack();
        }
    }

    goToNext = () => {
        const { currentIndex, reels, page, totalPages } = this.state;
        if (currentIndex < reels.length - 1) {
            const newIndex = currentIndex + 1;
            this.setState({ currentIndex: newIndex, isPaused: false }, () => {
                this.playCurrentReel();
                this.fetchLikeCount(reels[newIndex].id);
                this.fetchViewCount(reels[newIndex].id);
                this.fetchTags(reels[newIndex].id);
                this.fetchComments(reels[newIndex].id);
                this.recordView(reels[newIndex].id);
                // Preload next
                if (newIndex + 1 < reels.length) {
                    this.preloadReel(reels[newIndex + 1].id);
                }
                // Load more reels if near end. In random mode keep fetching (each page is a fresh
                // random draw), so ignore the totalPages ceiling and cycle pages to pull more.
                if (newIndex >= reels.length - 3) {
                    if (this.state.isRandom) {
                        const nextPage = page < totalPages ? page + 1 : 1;
                        this.setState({ page: nextPage }, () => this.fetchReels());
                    } else if (page < totalPages) {
                        this.setState({ page: page + 1 }, () => this.fetchReels());
                    }
                }
            });
        }
    }

    goToPrev = () => {
        const { currentIndex, reels } = this.state;
        if (currentIndex > 0) {
            this.setState({ currentIndex: currentIndex - 1, isPaused: false }, () => {
                this.playCurrentReel();
                this.fetchLikeCount(reels[currentIndex - 1].id);
                this.fetchViewCount(reels[currentIndex - 1].id);
                this.fetchTags(reels[currentIndex - 1].id);
                this.fetchComments(reels[currentIndex - 1].id);
                this.recordView(reels[currentIndex - 1].id);
            });
        }
    }

    togglePause = () => {
        const { reels, currentIndex, isPaused } = this.state;
        const reel = reels[currentIndex];
        if (!reel) return;

        const videoEl = this.videoRefs[reel.id];
        if (videoEl) {
            if (isPaused) {
                videoEl.play();
            } else {
                videoEl.pause();
            }
        }
        this.setState({ isPaused: !isPaused, showOverlay: true });
        if (this.overlayTimeout) clearTimeout(this.overlayTimeout);
        this.overlayTimeout = setTimeout(() => this.setState({ showOverlay: false }), 800);
    }

    playCurrentReel() {
        const { reels, currentIndex } = this.state;
        const reel = reels[currentIndex];
        if (!reel) return;

        // Pause all other videos
        Object.entries(this.videoRefs).forEach(([id, videoEl]) => {
            if (videoEl && id !== String(reel.id)) {
                videoEl.pause();
                videoEl.currentTime = 0;
            }
        });

        // Play current
        const videoEl = this.videoRefs[reel.id];
        if (videoEl) {
            videoEl.currentTime = 0;
            videoEl.play().catch(() => {});
        }
    }

    handleWheel = (event) => {
        // In grid mode, scrolling pages the grid by a full screen of reels.
        if (this.state.gridActive) {
            if (event.deltaY > 30) {
                this.scrollGrid(1);
            } else if (event.deltaY < -30) {
                this.scrollGrid(-1);
            }
            return;
        }
        if (event.deltaY > 30) {
            this.goToNext();
        } else if (event.deltaY < -30) {
            this.goToPrev();
        }
    }

    handleTouchStart = (event) => {
        if (event.touches.length === 2) {
            this.lastPinchDistance = this.getPinchDistance(event.touches);
        } else {
            this.touchStartY = event.touches[0].clientY;
        }
    }

    handleTouchMove = (event) => {
        if (event.touches.length === 2) {
            const currentDistance = this.getPinchDistance(event.touches);
            if (this.lastPinchDistance && currentDistance > this.lastPinchDistance * 1.3) {
                // Pinch-out detected — go fullscreen
                this.enterFullscreen();
                this.lastPinchDistance = null;
            }
        }
    }

    handleTouchEnd = (event) => {
        if (this.lastPinchDistance) {
            this.lastPinchDistance = null;
            return;
        }
        const touchEndY = event.changedTouches[0].clientY;
        const diff = this.touchStartY - touchEndY;
        // In grid mode, swipe pages the grid by a full screen of reels.
        if (this.state.gridActive) {
            if (diff > 50) {
                this.scrollGrid(1);
            } else if (diff < -50) {
                this.scrollGrid(-1);
            }
            return;
        }
        if (diff > 50) {
            this.goToNext();
        } else if (diff < -50) {
            this.goToPrev();
        }
    }

    getPinchDistance(touches) {
        const dx = touches[0].clientX - touches[1].clientX;
        const dy = touches[0].clientY - touches[1].clientY;
        return Math.sqrt(dx * dx + dy * dy);
    }

    enterFullscreen = () => {
        const el = this.containerRef.current;
        if (!el) return;

        if (document.fullscreenElement) return; // already fullscreen

        if (el.requestFullscreen) {
            el.requestFullscreen();
        } else if (el.webkitRequestFullscreen) {
            el.webkitRequestFullscreen();
        } else if (el.msRequestFullscreen) {
            el.msRequestFullscreen();
        }
    }

    toggleFullscreen = () => {
        if (document.fullscreenElement || document.webkitFullscreenElement) {
            if (document.exitFullscreen) {
                document.exitFullscreen();
            } else if (document.webkitExitFullscreen) {
                document.webkitExitFullscreen();
            }
            this.setState({ isCleanView: false });
        } else {
            this.enterFullscreen();
            this.setState({ isCleanView: true });
        }
    }

    handleFullscreenChange = () => {
        if (!document.fullscreenElement && !document.webkitFullscreenElement) {
            this.setState({ isCleanView: false });
        }
    }

    handleTimelineClick = (event) => {
        const timeline = this.timelineRef.current;
        if (!timeline) return;
        const rect = timeline.getBoundingClientRect();
        const clickX = event.clientX - rect.left;
        const ratio = Math.max(0, Math.min(1, clickX / rect.width));
        this.seekToRatio(ratio);
    }

    handleTimelineMouseDown = (event) => {
        event.preventDefault();
        this.setState({ isSeeking: true });
        this.handleTimelineClick(event);
        document.addEventListener('mousemove', this.handleTimelineMouseMove);
        document.addEventListener('mouseup', this.handleTimelineMouseUp);
    }

    handleTimelineMouseMove = (event) => {
        const timeline = this.timelineRef.current;
        if (!timeline) return;
        const rect = timeline.getBoundingClientRect();
        const clickX = event.clientX - rect.left;
        const ratio = Math.max(0, Math.min(1, clickX / rect.width));
        this.seekToRatio(ratio);
    }

    handleTimelineMouseUp = () => {
        this.setState({ isSeeking: false });
        document.removeEventListener('mousemove', this.handleTimelineMouseMove);
        document.removeEventListener('mouseup', this.handleTimelineMouseUp);
    }

    seekToRatio(ratio) {
        const { reels, currentIndex } = this.state;
        const reel = reels[currentIndex];
        if (!reel) return;
        const videoEl = this.videoRefs[reel.id];
        if (videoEl && videoEl.duration) {
            videoEl.currentTime = ratio * videoEl.duration;
            this.setState({ currentTime: videoEl.currentTime });
        }
    }

    formatTime(seconds) {
        if (!seconds || isNaN(seconds)) return '0:00';
        const mins = Math.floor(seconds / 60);
        const secs = Math.floor(seconds % 60);
        return mins + ':' + (secs < 10 ? '0' : '') + secs;
    }

    renderReelSlide(reel, index) {
        const { currentIndex, reelBlobUrls, loadingReelIds } = this.state;
        const isActive = index === currentIndex;
        const blobUrl = reelBlobUrls[reel.id];
        const isLoading = loadingReelIds[reel.id];

        return (
            <div
                key={reel.id}
                style={{
                    ...styles.reelSlide,
                    transform: `translateY(${(index - currentIndex) * 100}%)`,
                    transition: 'transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94)',
                }}
            >
                {blobUrl ? (
                    <video
                        ref={el => { this.videoRefs[reel.id] = el; }}
                        src={blobUrl}
                        style={styles.video}
                        // When auto-advance is on, don't loop the active reel so it can 'end'
                        // and trigger the next one. Non-active slides always loop (harmless, paused).
                        loop={!isActive || !this.state.autoAdvance}
                        playsInline
                        muted={false}
                        autoPlay={isActive}
                        onClick={(e) => this.handleVideoClick(e, reel.id)}
                        onEnded={() => this.handleReelEnded(reel.id)}
                    />
                ) : (
                    <div style={styles.loadingContainer}>
                        {isLoading ? (
                            <div style={styles.spinner}></div>
                        ) : (
                            <span style={styles.loadingText}>Loading reel...</span>
                        )}
                    </div>
                )}

                {/* Reel info overlay */}
                {!this.state.isCleanView && (
                    <div style={styles.infoOverlay}>
                        <div style={styles.caption}>
                            {reel.caption
                                ? (reel.caption.length > 100 ? reel.caption.substring(0, 100) + '...' : reel.caption)
                                : ''}
                        </div>
                        <div style={styles.metadata}>
                            <span style={styles.shortcode}>@{reel.shortcode}</span>
                            {reel.uploadDate && <span style={styles.uploadDate}> · {reel.uploadDate}</span>}
                            <span style={styles.viewCountInline}> · ▶ {this.state.viewCounts[reel.id] != null ? this.state.viewCounts[reel.id] : '—'}</span>
                            {/* Open the Instagram profile page in a new tab */}
                            <button
                                style={styles.profileBtn}
                                onClick={(e) => { e.stopPropagation(); this.openProfileInNewTab(reel); }}
                                title="Open profile in new tab"
                            >
                                👤
                            </button>
                        </div>
                    </div>
                )}

                {/* Like button and count */}
                {isActive && !this.state.isCleanView && (
                    <div style={styles.likeContainer}>
                        <button
                            style={{
                                ...styles.likeBtn,
                                color: (this.state.likeCounts[reel.id] > 0 || this.state.likeAnimatingIds[reel.id]) ? '#ff3040' : 'rgba(255,255,255,0.6)',
                                opacity: this.state.likingReelIds[reel.id] ? 0.5 : 1,
                                transform: this.state.likeAnimatingIds[reel.id] ? 'scale(1.4)' : 'scale(1)',
                            }}
                            onClick={(e) => { e.stopPropagation(); this.likeCurrentReel(1); }}
                            disabled={this.state.likingReelIds[reel.id]}
                            title="Like (L)"
                        >
                            {this.state.likeCounts[reel.id] > 0 ? '♥' : '♡'}
                        </button>
                        <span style={{
                            ...styles.likeCount,
                            transform: this.state.likeAnimatingIds[reel.id] ? 'scale(1.2)' : 'scale(1)',
                            transition: 'transform 0.3s ease',
                        }}>
                            {this.state.likeCounts[reel.id] != null ? this.state.likeCounts[reel.id] : '—'}
                        </span>

                        {/* Quick-like buttons: add multiple likes at once */}
                        <div style={styles.quickLikeRow}>
                            {[2, 5, 10].map(amount => (
                                <button
                                    key={amount}
                                    style={{ ...styles.quickLikeBtn, backgroundColor: likeColorFor(amount) }}
                                    onClick={(e) => { e.stopPropagation(); this.likeCurrentReel(amount); }}
                                    disabled={this.state.likingReelIds[reel.id]}
                                    title={'Like +' + amount}
                                >
                                    +{amount}
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* Floating heart animation on like, colored by the last like amount */}
                {isActive && this.state.likeAnimatingIds[reel.id] && (
                    <div style={styles.floatingHeartContainer}>
                        <span style={{ ...styles.floatingHeart, color: this.state.likeColorIds[reel.id] || DEFAULT_LIKE_COLOR }}>♥</span>
                    </div>
                )}

                {/* Tags: view / add / delete hashtags for this reel */}
                {isActive && !this.state.isCleanView && this.renderTagsPanel(reel.id)}

                {/* Comments: view all / add / delete comments for this reel */}
                {isActive && !this.state.isCleanView && this.renderCommentsPanel(reel.id)}
            </div>
        );
    }

    renderTagsPanel(reelId) {
        const tags = this.state.tagsByReelId[reelId] || [];
        // tags panel visibility is a single global preference (hidden by default)
        const isOpen = this.state.showTags;
        const isBusy = !!this.state.tagBusyReelIds[reelId];
        const inputValue = this.state.tagInputByReelId[reelId] || '';
        const suggestions = this.state.tagSuggestionsByReelId[reelId] || [];

        return (
            <div style={styles.tagsContainer} onClick={(e) => e.stopPropagation()}>
                <button
                    style={styles.tagsToggleBtn}
                    onClick={(e) => { e.stopPropagation(); this.toggleTagsPanel(); }}
                    title="Tags"
                >
                    🏷️ {tags.length > 0 ? tags.length : ''} {isOpen ? '▾' : '▸'}
                </button>

                {isOpen && (
                    <div style={styles.tagsPanel}>
                        <div style={styles.tagChipsWrap}>
                            {tags.length === 0 ? (
                                <span style={styles.tagsEmpty}>No tags yet</span>
                            ) : (
                                tags.map(tag => (
                                    <span key={tag} style={styles.tagChip}>
                                        #{tag}
                                        <button
                                            style={styles.tagChipRemove}
                                            onClick={(e) => { e.stopPropagation(); this.deleteTag(reelId, tag); }}
                                            disabled={isBusy}
                                            title={'Remove #' + tag}
                                        >
                                            ✕
                                        </button>
                                    </span>
                                ))
                            )}
                        </div>
        <div style={styles.tagInputRow}>
                            <div style={styles.tagInputWrap}>
                                <input
                                    style={styles.tagInput}
                                    type="text"
                                    placeholder="add a hashtag..."
                                    value={inputValue}
                                    onChange={(e) => this.handleTagInputChange(reelId, e.target.value)}
                                    onKeyDown={(e) => this.handleTagInputKeyDown(e, reelId)}
                                    disabled={isBusy}
                                />
                                {/* typeahead suggestions from existing tags (POST /v1/tags/search) */}
                                {suggestions.length > 0 && (
                                    <div style={styles.tagSuggestions}>
                                        {suggestions.map(s => (
                                            <button
                                                key={s.name}
                                                style={styles.tagSuggestionItem}
                                                onMouseDown={(e) => { e.preventDefault(); e.stopPropagation(); this.selectTagSuggestion(reelId, s.name); }}
                                                title={'Add #' + s.name}
                                            >
                                                <span>#{s.name}</span>
                                                <span style={styles.tagSuggestionCount}>{s.usageCount}</span>
                                            </button>
                                        ))}
                                    </div>
                                )}
                            </div>
                            <button
                                style={styles.tagAddBtn}
                                onClick={(e) => { e.stopPropagation(); this.addTag(reelId); }}
                                disabled={isBusy || !inputValue.trim()}
                                title="Add tag"
                            >
                                +
                            </button>
                        </div>
                    </div>
                )}
            </div>
        );
    }

    // Formats an engagement timestamp (ISO string or epoch) into a short local date-time.
    formatCommentDate(value) {
        if (!value) return '';
        const d = new Date(value);
        if (isNaN(d.getTime())) return '';
        return d.toLocaleString();
    }

    renderCommentsPanel(reelId) {
        const comments = this.state.commentsByReelId[reelId] || [];
        // comments panel visibility is a single global preference (hidden by default)
        const isOpen = this.state.showComments;
        const isBusy = !!this.state.commentBusyReelIds[reelId];
        const inputValue = this.state.commentInputByReelId[reelId] || '';

        return (
            <div style={styles.commentsContainer} onClick={(e) => e.stopPropagation()}>
                <button
                    style={styles.commentsToggleBtn}
                    onClick={(e) => { e.stopPropagation(); this.toggleCommentsPanel(); }}
                    title="Comments"
                >
                    💬 {comments.length > 0 ? comments.length : ''} {isOpen ? '▾' : '▸'}
                </button>

                {isOpen && (
                    <div style={styles.commentsPanel}>
                        <div style={styles.commentsList}>
                            {comments.length === 0 ? (
                                <span style={styles.commentsEmpty}>No comments yet</span>
                            ) : (
                                comments.map(c => (
                                    <div key={c.id} style={styles.commentItem}>
                                        <div style={styles.commentBody}>
                                            <div style={styles.commentText}>{c.comment}</div>
                                            <div style={styles.commentDate}>{this.formatCommentDate(c.createdOn)}</div>
                                        </div>
                                        <button
                                            style={styles.commentDeleteBtn}
                                            onClick={(e) => { e.stopPropagation(); this.deleteComment(reelId, c.id); }}
                                            disabled={isBusy}
                                            title="Delete comment"
                                        >
                                            ✕
                                        </button>
                                    </div>
                                ))
                            )}
                        </div>
                        <div style={styles.commentInputRow}>
                            <input
                                style={styles.commentInput}
                                type="text"
                                placeholder="add a comment..."
                                value={inputValue}
                                onChange={(e) => this.handleCommentInputChange(reelId, e.target.value)}
                                onKeyDown={(e) => this.handleCommentInputKeyDown(e, reelId)}
                                disabled={isBusy}
                            />
                            <button
                                style={styles.commentAddBtn}
                                onClick={(e) => { e.stopPropagation(); this.addComment(reelId); }}
                                disabled={isBusy || !inputValue.trim()}
                                title="Add comment"
                            >
                                ➤
                            </button>
                        </div>
                    </div>
                )}
            </div>
        );
    }

    // Computes the number of grid columns that lays out `count` tiles cleanly.
    // Up to 4 tiles each get their own single row (e.g. 4 reels -> 4 columns, one row).
    gridColumnsFor(count) {
        if (count <= 1) return 1;
        if (count <= 4) return count; // 2-4 tiles -> one row (2/3/4 columns)
        if (count <= 8) return 4;     // 5-8 tiles -> 4 columns
        return 5;                     // 9-10 tiles -> 5 columns
    }

    renderGrid() {
        const { gridCount, gridReels, reelBlobUrls, loadingReelIds } = this.state;
        const columns = this.gridColumnsFor(gridReels.length || gridCount);

        return (
            <div style={styles.gridOverlay} onClick={(e) => e.stopPropagation()}>
                {/* Header: count selector + close */}
                <div style={styles.gridHeader}>
                    <div style={styles.gridCountControl}>
                        <button
                            style={styles.gridStepBtn}
                            onClick={() => this.setGridCount(gridCount - 1)}
                            disabled={gridCount <= GRID_MIN}
                            title="Fewer reels"
                        >
                            −
                        </button>
                        <span style={styles.gridCountLabel}>{gridCount} reels</span>
                        <button
                            style={styles.gridStepBtn}
                            onClick={() => this.setGridCount(gridCount + 1)}
                            disabled={gridCount >= GRID_MAX}
                            title="More reels"
                        >
                            +
                        </button>
                        <input
                            type="range"
                            min={GRID_MIN}
                            max={GRID_MAX}
                            value={gridCount}
                            onChange={(e) => this.setGridCount(parseInt(e.target.value, 10))}
                            style={styles.gridSlider}
                        />
                    </div>
                    <div style={styles.gridScrollControl}>
                        <button
                            style={styles.gridScrollBtn}
                            onClick={() => this.scrollGrid(-1)}
                            disabled={this.state.gridStart <= 0}
                            title="Previous reels"
                        >
                            ▲
                        </button>
                        <button
                            style={styles.gridScrollBtn}
                            onClick={() => this.scrollGrid(1)}
                            disabled={this.state.gridStart + gridCount >= this.state.reels.length}
                            title="Next reels"
                        >
                            ▼
                        </button>
                        <button style={styles.gridCloseBtn} onClick={this.closeGrid}>
                            ✕ Close
                        </button>
                    </div>
                </div>

                {/* Grid of reels playing simultaneously */}
                <div
                    style={{
                        ...styles.grid,
                        gridTemplateColumns: `repeat(${columns}, 1fr)`,
                    }}
                >
                    {gridReels.map((reel, tileIndex) => {
                        const blobUrl = reelBlobUrls[reel.id];
                        const isLoading = loadingReelIds[reel.id];
                        return (
                            <div
                                key={reel.id + '-' + tileIndex}
                                style={styles.gridTile}
                                onClick={() => this.openReelFromGrid(reel.id)}
                                title="Open full screen"
                            >
                                {blobUrl ? (
                                    <video
                                        src={blobUrl}
                                        style={styles.gridVideo}
                                        autoPlay
                                        loop
                                        muted
                                        playsInline
                                    />
                                ) : (
                                    <div style={styles.gridTileLoading}>
                                        {isLoading ? <div style={styles.spinner}></div> : 'Loading…'}
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        );
    }

    render() {
        const { isLoaded, reels, currentIndex, isPaused, showOverlay, isCleanView, selectedTags, tagMatchMode } = this.state;

        if (!isLoaded) return <Loading />;

        if (reels.length === 0) {
            return (
                <div style={styles.emptyState}>
                    <h2>No downloaded reels available</h2>
                    <p>Download some reels first to view them here.</p>
                    <button onClick={() => this.props.history.goBack()} style={styles.backBtn}>← Go Back</button>
                </div>
            );
        }

        return (
            <div
                ref={this.containerRef}
                style={styles.container}
                onWheel={this.handleWheel}
                onTouchStart={this.handleTouchStart}
                onTouchMove={this.handleTouchMove}
                onTouchEnd={this.handleTouchEnd}
            >
                {/* Reel slides */}
                <div style={styles.slidesWrapper}>
                    {reels.map((reel, index) => {
                        // Virtualization: only render slides within ±1 of current
                        if (Math.abs(index - currentIndex) > 1) return null;
                        return this.renderReelSlide(reel, index);
                    })}
                </div>

                {/* View-by-tags filter: searchable multi-tag selector + AND/OR toggle.
                    Keystrokes are kept from reaching the viewer's global key handlers. */}
                {!isCleanView && (
                    <div
                        style={styles.tagFilterBar}
                        onClick={(e) => e.stopPropagation()}
                        onKeyDown={(e) => e.stopPropagation()}
                    >
                        <span style={styles.tagFilterIcon} title="View reels by tags">🏷️</span>
                        <div style={styles.tagFilterSelectWrap}>
                            <AsyncSelect
                                isMulti
                                cacheOptions
                                defaultOptions
                                placeholder="View by tags…"
                                value={selectedTags.map(t => ({ value: t, label: t }))}
                                loadOptions={this.loadTagFilterOptions}
                                onChange={this.handleTagFilterChange}
                                noOptionsMessage={() => 'No matching tags'}
                                menuPortalTarget={document.body}
                                styles={{ menuPortal: base => ({ ...base, zIndex: 100000 }) }}
                            />
                        </div>
                        <select
                            style={styles.tagFilterModeSelect}
                            value={tagMatchMode}
                            onChange={(e) => this.handleTagModeChange(e.target.value)}
                            title="Any (OR) = reels with any of the tags; All (AND) = reels with all tags"
                        >
                            <option value="OR">Any (OR)</option>
                            <option value="AND">All (AND)</option>
                        </select>
                    </div>
                )}

                {/* Pause/Play overlay indicator */}
                {showOverlay && (
                    <div style={styles.pauseOverlay}>
                        <span style={styles.pauseIcon}>{isPaused ? '▶' : '⏸'}</span>
                    </div>
                )}

                {/* Navigation arrows */}
                {!isCleanView && (
                    <div style={styles.navContainer}>
                        <button
                            style={{ ...styles.navBtn, opacity: currentIndex > 0 ? 1 : 0.3 }}
                            onClick={this.goToPrev}
                            disabled={currentIndex <= 0}
                        >
                            ▲
                        </button>
                        <span style={styles.counter}>{currentIndex + 1} / {reels.length}</span>
                        <button
                            style={{ ...styles.navBtn, opacity: currentIndex < reels.length - 1 ? 1 : 0.3 }}
                            onClick={this.goToNext}
                            disabled={currentIndex >= reels.length - 1}
                        >
                            ▼
                        </button>
                    </div>
                )}

                {/* Close button */}
                {!isCleanView && (
                    <button
                        style={styles.closeBtn}
                        onClick={() => this.props.history.goBack()}
                        title="Close (Esc)"
                    >
                        ✕
                    </button>
                )}

                {/* Fullscreen button */}
                <button
                    style={styles.fullscreenBtn}
                    onClick={this.toggleFullscreen}
                    title="Fullscreen (F)"
                >
                    {isCleanView ? '⛶' : '⛶'}
                </button>

                {/* Auto-advance toggle: play next reel automatically when the current ends */}
                {!isCleanView && (
                    <button
                        style={{
                            ...styles.autoAdvanceBtn,
                            color: this.state.autoAdvance ? '#2eb85c' : 'rgba(255,255,255,0.6)',
                        }}
                        onClick={this.toggleAutoAdvance}
                        title={this.state.autoAdvance ? 'Auto-advance: on' : 'Auto-advance: off'}
                    >
                        {this.state.autoAdvance ? '⏭' : '🔁'}
                    </button>
                )}

                {/* Grid: view X reels simultaneously */}
                {!isCleanView && (
                    <button
                        style={styles.gridBtn}
                        onClick={this.openGrid}
                        title="Grid — view multiple reels at once"
                    >
                        ▦
                    </button>
                )}

                {/* Grid overlay */}
                {this.state.gridActive && this.renderGrid()}

                {/* Timeline scroller */}
                {!isCleanView && (
                    <div style={styles.timelineContainer}>
                        <span style={styles.timeLabel}>{this.formatTime(this.state.currentTime)}</span>
                        <div
                            ref={this.timelineRef}
                            style={styles.timelineTrack}
                            onMouseDown={this.handleTimelineMouseDown}
                        >
                            <div
                                style={{
                                    ...styles.timelineFill,
                                    width: this.state.duration > 0
                                        ? `${(this.state.currentTime / this.state.duration) * 100}%`
                                        : '0%',
                                }}
                            />
                            <div
                                style={{
                                    ...styles.timelineThumb,
                                    left: this.state.duration > 0
                                        ? `${(this.state.currentTime / this.state.duration) * 100}%`
                                        : '0%',
                                }}
                            />
                        </div>
                        <span style={styles.timeLabel}>{this.formatTime(this.state.duration)}</span>
                    </div>
                )}

                {/* Progress bar (reel position) */}
                {!isCleanView && (
                    <div style={styles.progressBarContainer}>
                        <div style={{ ...styles.progressBar, width: `${((currentIndex + 1) / reels.length) * 100}%` }}></div>
                    </div>
                )}
            </div>
        );
    }
}

